#!ibl edition=2
$e0 = [limbs:browser]{op:"evaluate", expression:"Array.from(document.querySelectorAll('.col')).filter(c=>['지연','오늘 처리'].includes(c.dataset.col)).map(c=>c.dataset.col+':'+Array.from(c.querySelectorAll('.card')).map(x=>x.dataset.id+'@'+Math.round(x.getBoundingClientRect().top)).join(',')).join(' | ') + ' scrollY=' + window.scrollY"}
$s = [limbs:browser]{op:"snapshot"}
$card = ($s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"W-1011")})
$today = ($s.snapshot >> [table:filter]{where:($e)=>$e.role=="region" and contains($e.name,"오늘 처리")})
$d = [try] { [limbs:browser]{op:"drag", source_ref:$card[0].ref, target_ref:$today[0].ref} } [catch] { {failed:true, code:$error.code, message:$error.message} }
$e1 = [limbs:browser]{op:"evaluate", expression:"Array.from(document.querySelectorAll('.col')).filter(c=>['지연','오늘 처리'].includes(c.dataset.col)).map(c=>c.dataset.col+':'+Array.from(c.querySelectorAll('.card')).map(x=>x.dataset.id).join(',')).join(' | ')"}
return {before:$e0.result, card:$card, today:$today, drag:$d, after:$e1.result}
